in vec3 vPosition; // Position of the vertex passed from the vertex shader

uniform mat4 viewMatrix; // View matrix for transforming world coordinates to eye space
uniform mat4 projectionMatrix; // Projection matrix for transforming eye space to clip space
uniform float fovY; // Field of view angle in radians
uniform int width; // Width of the screen
uniform int height; // Height of the screen
uniform sampler2D heightMap; // Texture containing the height information

out vec4 FragColor;

float calculateDistance(vec2 p)
{
    return texture(heightMap, p).r * 10.0; // Scale the height value appropriately
}

vec3 castRay(vec2 direction)
{
    float t = 0.0;
    while (t < 100.0) // Maximum distance to check
    {
        vec2 pos = vec2(t * direction.x, t * direction.y);
        if (pos.x > 1.0 || pos.x < -1.0 || pos.y > 1.0 || pos.y < -1.0)
            break;

        float dist = calculateDistance(pos);
        if (dist > 0.0)
        {
            return vec3(dist, 0.5, 1.0); // Return color based on distance
        }
        t += 0.1; // Increment step size
    }
    return vec3(0.0, 0.0, 0.0); // Return black if no intersection found
}

void main()
{
    vec2 uv = (vPosition.xy + 1.0) / 2.0; // Convert vertex position to UV coordinates

    vec2 dir = normalize(vec2(uv.x * tan(fovY / 2.0), -uv.y * tan(fovY / 2.0)));

    vec3 color = castRay(dir);

    FragColor = vec4(color, 1.0);
}
```

