### Step 2: Create the Client Class

Create a new Java class named `KubernetesLogClient`.

```java
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class KubernetesLogClient {

    private final String apiServerUrl;
    private final CloseableHttpClient httpClient;

    public KubernetesLogClient(String apiServerUrl) {
        this.apiServerUrl = apiServerUrl;
        this.httpClient = HttpClients.createDefault();
    }

    public String getPodLogs(String namespace, String podName) throws Exception {
        // Construct the URL for fetching pod logs
        String url = String.format("%s/api/v1/namespaces/%s/pods/%s/log", apiServerUrl, namespace, podName);

        // Create an HTTP GET request
        HttpGet request = new HttpGet(url);

        try (CloseableHttpResponse response = httpClient.execute(request)) {
            // Check if the request was successful
            if (response.getStatusLine().getStatusCode() == 200) {
                return EntityUtils.toString(response.getEntity());
            } else {
                throw new RuntimeException("Failed to retrieve pod logs: " + response.getStatusLine().getReasonPhrase());
            }
        }
    }

    public void close() throws IOException {
        httpClient.close();
    }
}
```

### Step 3: Use the Client

Now you can use the `KubernetesLogClient` to fetch pod logs.

```java
public class Main {
    public static void main(String[] args) {
        try {
            String apiServerUrl = "https://your-kubernetes-api-server";
            KubernetesLogClient client = new KubernetesLogClient(apiServerUrl);

            String logs = client.getPodLogs("default", "my-pod");
            System.out.println(logs);

            client.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

