```cpp
#include <ap_int.h>
#include <hls_stream.h>

// Define data types
typedef ap_uint<8> uint8_t;
typedef ap_fixed<16, 8> fixed_point;

// Function to perform matrix multiplication
void matmul(const fixed_point A[28*28], const fixed_point B[784*10], fixed_point C[10]) {
    #pragma HLS INTERFACE m_axi port=A bundle=gmem0
    #pragma HLS INTERFACE m_axi port=B bundle=gmem1
    #pragma HLS INTERFACE m_axi port=C bundle=gmem2

    #pragma HLS DATAFLOW

    // Temporary storage for intermediate results
    fixed_point temp[10];

    // Perform matrix multiplication
    for (int i = 0; i < 10; ++i) {
        temp[i] = 0;
        for (int j = 0; j < 28*28; ++j) {
            temp[i] += A[j] * B[j*10 + i];
        }
    }

    // Store the result in C
    for (int i = 0; i < 10; ++i) {
        C[i] = temp[i];
    }
}

// Function to apply softmax activation function
void softmax(fixed_point input[10], fixed_point output[10]) {
    #pragma HLS INTERFACE s_axilite port=input bundle=control
    #pragma HLS INTERFACE s_axilite port=output bundle=control

    #pragma HLS ARRAY_PARTITION variable=input complete dim=1
    #pragma HLS ARRAY_PARTITION variable=output complete dim=1

    // Find the maximum value in the input array
    fixed_point max_val = input[0];
    for (int i = 1; i < 10; ++i) {
        if (input[i] > max_val) {
            max_val = input[i];
        }
    }

    // Subtract the maximum value from each element
    fixed_point sum_exp = 0;
    for (int i = 0; i < 10; ++i) {
        fixed_point exp_val = exp(input[i] - max_val);
        sum_exp += exp_val;
        output[i] = exp_val;
    }

    // Normalize the values
    for (int i = 0; i < 10; ++i) {
        output[i] /= sum_exp;
    }
}

// Main function to classify the input image
void classify_image(uint8_t input_image[28*28], int &predicted_label) {
    #pragma HLS INTERFACE s_axilite port=input_image bundle=control
    #pragma HLS INTERFACE s_axilite port=predicted_label bundle=control

    #pragma HLS ARRAY_PARTITION variable=input_image complete dim=1

    // Convert input image to fixed-point format
    fixed_point A[28*28];
    for (int i = 0; i < 28*28; ++i) {
        A[i] = input_image[i];
    }

    // Weights for the hidden layer
    fixed_point weights_hidden[784*10] = { /* Initialize with appropriate values */ };

    // Output from the hidden layer
    fixed_point hidden_output[10];

    // Perform matrix multiplication
    matmul(A, weights_hidden, hidden_output);

    // Apply softmax activation function
    fixed_point softmax_output[10];
    softmax(hidden_output, softmax_output);

    // Find the index of the maximum value in the softmax output
    predicted_label = 0;
    for (int i = 1; i < 10; ++i) {
        if (softmax_output[i] > softmax_output[predicted_label]) {
            predicted_label = i;
        }
    }
}
```

