            }
            finally
            {
                // Close the client
                client.Close();
            }
        }
    }
}
```

### Notes:
- Replace `YourNamespace` with the actual namespace where the generated classes are located.
- Replace `YourServiceClient` and `YourMethod` with the appropriate client class and method names generated from the WSDL.

By following these steps, you can easily generate and use C# classes from a WSDL file in Visual Studio.

