```rust
use std::io;

fn is_prime(n: u64) -> bool {
    if n <= 1 {
        return false;
    }
    for i in 2..=((n as f64).sqrt() as u64) {
        if n % i == 0 {
            return false;
        }
    }
    true
}

fn main() {
    let mut input = String::new();
    println!("Enter the range (e.g., '10'): ");
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let range: u64 = input.trim().parse().expect("Please enter a valid number");

    for num in 2..=range {
        if is_prime(num) {
            print!("{} ", num);
        }
    }
    println!();
}
```

