```swift
import UIKit

class ViewController: IMKExtensionViewController {

    override func viewDidLoad() {
        super.viewDidLoad()

        // Set up the button views
        let button1 = UIButton(type: .system)
        button1.setTitle("Button 1", for: .normal)
